// Integration checks against the project generated by ios:prepare. Ruby and
// xcodeproj are required, but no Xcode, real profiles or signing keys are used.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { cpSync, mkdtempSync, mkdirSync, readFileSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { basename, dirname, join, resolve } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";


const mobile = fileURLToPath(new URL("../", import.meta.url));
const require = createRequire(import.meta.url);
const { checkAppId } = require("../node_modules/@capacitor/cli/dist/common.js");
const { loadConfig } = require("../node_modules/@capacitor/cli/dist/config.js");
const runWithEnvironment = (cwd, script, environment, ...args) => spawnSync("ruby", [join(mobile, "scripts", script), ...args], {
  cwd, encoding: "utf8", env: { ...process.env, BUILD_NUMBER: "37", ANZEN_APNS_ENVIRONMENT: "production", ...environment },
});
const run = (cwd, script, ...args) => runWithEnvironment(cwd, script, {}, ...args);
const success = (result) => assert.equal(result.status, 0, `${result.error ?? ""}\n${result.stdout}\n${result.stderr}`);
const ruby = (cwd, code) => {
  const result = spawnSync("ruby", ["-rxcodeproj", "-rjson", "-e", code], { cwd, encoding: "utf8" });
  success(result);
  return result.stdout;
};
const fixture = (t) => {
  const cwd = mkdtempSync(join(tmpdir(), "anzen-ios-test-"));
  assert.equal(dirname(resolve(cwd)), resolve(tmpdir()));
  assert.ok(basename(cwd).startsWith("anzen-ios-test-"));
  t.after(() => rmSync(cwd, { recursive: true, force: true }));
  // Copy just the App project/metadata, never Pods or the web asset bundle.
  const native = join(cwd, "ios/App/App");
  mkdirSync(join(native, "Base.lproj"), { recursive: true });
  cpSync(join(mobile, "ios/App/App.xcodeproj"), join(cwd, "ios/App/App.xcodeproj"), { recursive: true });
  cpSync(join(mobile, "ios-resources"), join(cwd, "ios-resources"), { recursive: true });
  for (const file of ["Info.plist", "capacitor.config.json", "AppDelegate.swift", "NativeVault.swift", "PrivacyInfo.xcprivacy", "Base.lproj/Main.storyboard"]) {
    cpSync(join(mobile, "ios/App/App", file), join(native, file));
  }
  success(run(cwd, "configure-ios.rb"));
  return cwd;
};
const editSetting = (cwd, name, value, configuration = "Release") => ruby(cwd, `
  project = Xcodeproj::Project.open('ios/App/App.xcodeproj')
  config = project.targets.find { |t| t.name == 'App' }.build_configurations.find { |c| c.name == ${JSON.stringify(configuration)} }
  config.build_settings[${JSON.stringify(name)}] = ${JSON.stringify(value)}
  project.save
`);
const rejects = (cwd, message, ...args) => {
  const result = run(cwd, "verify-ios.rb", ...args);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, message);
};

test("the pinned CLI accepts the generation ID and rejects the registered Apple ID", async () => {
  const config = await loadConfig();
  assert.equal(config.app.appId, "jp.anzenaiportal.app");
  assert.equal(await checkAppId(config, config.app.appId), null);
  assert.match(await checkAppId(config, "jp.anzen-ai-portal.app"), /Invalid App ID/);
});

test('real CLI sync runs the identity hook on fresh and existing SPM projects', t => {
  const cwd = mkdtempSync(join(tmpdir(), 'anzen-ios-test-'));
  assert.equal(dirname(resolve(cwd)), resolve(tmpdir()));
  assert.ok(basename(cwd).startsWith('anzen-ios-test-'));
  t.after(() => rmSync(cwd, { recursive: true, force: true }));
  cpSync(join(mobile, 'scripts'), join(cwd, 'scripts'), { recursive: true });
  cpSync(join(mobile, 'ios-resources'), join(cwd, 'ios-resources'), { recursive: true });
  // Minimal web payload; no 1.2 GB copy, network, real credentials or Xcode.
  mkdirSync(join(cwd, 'out'));
  writeFileSync(join(cwd, 'out/index.html'), '<!doctype html><title>fixture</title>');
  const pkg = JSON.parse(readFileSync(join(mobile, 'package.json'), 'utf8'));
  writeFileSync(join(cwd, 'package.json'), JSON.stringify(pkg));
  cpSync(join(mobile, 'capacitor.config.ts'), join(cwd, 'capacitor.config.ts'));
  // Installed locked dependencies remain in place and are read through a junction.
  symlinkSync(join(mobile, 'node_modules'), join(cwd, 'node_modules'), 'junction');
  for (const [number, command] of [['41', ['add', 'ios', '--packagemanager', 'SPM']], ['42', ['sync', 'ios']], ['43', ['sync', 'ios']]]) {
    const env = { ...process.env, BUILD_NUMBER: number, ANZEN_APNS_ENVIRONMENT: 'production', CAPACITOR_TELEMETRY_DISABLED: '1' };
    for (const key of Object.keys(env)) if (/(KEY|TOKEN|SECRET|PASSWORD|DATABASE|DIRECT_URL|POSTGRES|PRISMA)/i.test(key)) delete env[key];
    success(spawnSync(process.execPath, [join(mobile, 'node_modules/@capacitor/cli/bin/capacitor'), ...command], { cwd, env, encoding: 'utf8' }));
    success(runWithEnvironment(cwd, 'verify-ios.rb', { BUILD_NUMBER: number }));
  }
});

test("configuration restores every App build configuration and is idempotent", (t) => {
  const cwd = fixture(t);
  success(run(cwd, "verify-ios.rb"));
  const file = join(cwd, "ios/App/App.xcodeproj/project.pbxproj");
  const before = readFileSync(file, "utf8");
  success(run(cwd, "configure-ios.rb"));
  assert.equal(readFileSync(file, "utf8"), before);
  editSetting(cwd, "PRODUCT_BUNDLE_IDENTIFIER", "jp.anzenaiportal.app", "Debug");
  editSetting(cwd, "PRODUCT_BUNDLE_IDENTIFIER", "jp.anzenaiportal.app", "Release");
  success(run(cwd, "configure-ios.rb"));
  success(run(cwd, "verify-ios.rb"));
});

for (const configuration of ["Debug", "Release"]) {
  test(`verification rejects a different Bundle ID in ${configuration}`, (t) => {
    const cwd = fixture(t);
    editSetting(cwd, "PRODUCT_BUNDLE_IDENTIFIER", "jp.anzenaiportal.app", configuration);
    rejects(cwd, new RegExp(`Bundle ID mismatch in ${configuration}`));
  });
}

test("verification rejects a stale build number and runtime ID from cap sync", (t) => {
  const cwd = fixture(t);
  editSetting(cwd, "CURRENT_PROJECT_VERSION", "1");
  rejects(cwd, /Build number mismatch/);
  success(run(cwd, "configure-ios.rb"));
  const file = join(cwd, "ios/App/App/capacitor.config.json");
  const config = JSON.parse(readFileSync(file, "utf8"));
  config.appId = "jp.anzenaiportal.app";
  writeFileSync(file, JSON.stringify(config));
  rejects(cwd, /runtime Bundle ID mismatch/);
});

test("verification rejects a literal Info.plist Bundle ID", (t) => {
  const cwd = fixture(t);
  ruby(cwd, `path = 'ios/App/App/Info.plist'; p = Xcodeproj::Plist.read_from_path(path); p['CFBundleIdentifier'] = 'jp.anzenaiportal.app'; Xcodeproj::Plist.write_to_path(p, path)`);
  rejects(cwd, /Info.plist Bundle ID mismatch/);
});

test("verification detects missing native resources and development APNs for store export", t => {
  const cwd = fixture(t);
  writeFileSync(join(cwd, 'ios/App/App/NativeVault.swift'), '// damaged');
  rejects(cwd, /Native plugin differs from source/);
  cpSync(join(mobile, 'ios-resources/NativeVault.swift'), join(cwd, 'ios/App/App/NativeVault.swift'));
  success(run(cwd, 'verify-ios.rb'));
  const invalid = runWithEnvironment(cwd, 'configure-ios.rb', { BUILD_NUMBER: '0' });
  assert.notEqual(invalid.status, 0);
  assert.match(invalid.stderr, /Invalid build number/);
  success(runWithEnvironment(cwd, 'configure-ios.rb', { ANZEN_APNS_ENVIRONMENT: 'development' }));
  ruby(cwd, "Xcodeproj::Plist.write_to_path({'method'=>'app-store','provisioningProfiles'=>{'jp.anzen-ai-portal.app'=>'fixture-profile'}}, 'export.plist')");
  const result = runWithEnvironment(cwd, 'verify-ios.rb', { ANZEN_APNS_ENVIRONMENT: 'development' }, join(cwd, 'export.plist'));
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /Production APNs required/);
});

test("export verification requires matching App Store profiles and applied signing settings", (t) => {
  const cwd = fixture(t);
  const options = join(cwd, "export.plist");
  const writeOptions = (id, method = "app-store-connect") => ruby(cwd, `
    Xcodeproj::Plist.write_to_path({'method' => ${JSON.stringify(method)}, 'provisioningProfiles' => {${JSON.stringify(id)} => 'fixture-profile'}}, 'export.plist')
  `);
  writeOptions("jp.anzenaiportal.app");
  rejects(cwd, /profile missing for registered Bundle ID/, options);
  writeOptions("jp.anzen-ai-portal.app", "development");
  rejects(cwd, /App Store export method required/, options);
  writeOptions("jp.anzen-ai-portal.app");
  rejects(cwd, /Signing team missing/, options);
  for (const configuration of ["Debug", "Release"]) {
    editSetting(cwd, "DEVELOPMENT_TEAM", "TESTTEAM01", configuration);
    editSetting(cwd, "CODE_SIGN_STYLE", "Manual", configuration);
    editSetting(cwd, "PROVISIONING_PROFILE_SPECIFIER", "fixture-profile", configuration);
  }
  success(run(cwd, "verify-ios.rb", options));
  editSetting(cwd, "PROVISIONING_PROFILE_SPECIFIER", "");
  rejects(cwd, /Provisioning profile missing/, options);
});

test("export verification also accepts Codemagic's Xcode-managed profile settings", (t) => {
  const cwd = fixture(t);
  ruby(cwd, `
    project = Xcodeproj::Project.open('ios/App/App.xcodeproj')
    target = project.targets.find { |t| t.name == 'App' }
    project.root_object.attributes['TargetAttributes'][target.uuid]['ProvisioningStyle'] = 'Automatic'
    target.build_configurations.each { |c| c.build_settings['DEVELOPMENT_TEAM'] = 'TESTTEAM01'; c.build_settings.delete('CODE_SIGN_STYLE'); c.build_settings.delete('PROVISIONING_PROFILE_SPECIFIER') }
    project.save
    Xcodeproj::Plist.write_to_path({'method' => 'app-store', 'provisioningProfiles' => {'jp.anzen-ai-portal.app' => 'fixture-profile'}}, 'export.plist')
  `);
  success(run(cwd, "verify-ios.rb", join(cwd, "export.plist")));
});
